(()=>{'use strict';
 const P=window.LineMeasurementPhysics,$=id=>document.getElementById(id),motion=matchMedia('(prefers-reduced-motion: reduce)'),runs=new Map(),controllers=[];
 const grid=(a,b,n=501)=>Array.from({length:n},(_,i)=>a+(b-a)*i/(n-1)),fmt=(v,d=3)=>v===null?'无法反演':v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
 const active=host=>!document.body.classList.contains('reader-ready')||host.closest('.reader-slide')?.classList.contains('is-active');
 function stop(id){const r=runs.get(id);if(!r)return;cancelAnimationFrame(r.frame);runs.delete(id);$(id+'-play').textContent=r.label;$(id+'-play').setAttribute('aria-pressed','false');r.save();}
 const line=(p,data,color,dash='')=>p.layer.append('path').datum(data).attr('d',d3.line().x(d=>p.x(d.x)).y(d=>p.y(d.y))).attr('fill','none').attr('stroke',color).attr('stroke-width',2).attr('stroke-dasharray',dash);
 for(const lab of window.MeasurementLabSpecs||[]){const id=lab.id,host=$(id+'-lab');if(!host)continue;const inputs=Object.fromEntries(lab.params.map(p=>[p.key,$(id+'-'+p.key)])),storage='galaxies-measurement-v30-'+id;let cached={};try{cached=JSON.parse(localStorage.getItem(storage)||'{}');}catch{}
  for(const p of lab.params)if(Number.isFinite(cached[p.key]))inputs[p.key].value=Math.max(p.min,Math.min(p.max,cached[p.key]));
  const state=()=>Object.fromEntries(lab.params.map(p=>[p.key,+inputs[p.key].value])),save=()=>{try{localStorage.setItem(storage,JSON.stringify(state()));}catch{}};
  window.BookSources=Object.assign(window.BookSources||{},{[id+'-lab']:{title:lab.title,pages:lab.pages.join('–'),pdf:lab.pages.map(p=>p+22).join('–'),section:lab.source,body:lab.assumptions}});
  function legend(items){$(id+'-legend').replaceChildren(...items.map(([name,color,dash])=>{const s=document.createElement('span');s.textContent=name;s.style.setProperty('--legend-color',color);s.style.setProperty('--legend-style',typeof dash==='string'?dash:dash?'dashed':'solid');return s;}));}
  let bench,profilePath,scanGroup,scanLine,scanDot,project;
  if(id==='line-spread'){
   bench=host.querySelector('.measurement-bench-stage svg');bench.setAttribute('tabindex','0');bench.setAttribute('role','group');const plane=LineBenchProjection.detector.worldToSvg;
   project=(x,y)=>[plane.origin[0]+x*plane.xUnit[0]+y*plane.yUnit[0],plane.origin[1]+x*plane.xUnit[1]+y*plane.yUnit[1]];
   bench.addEventListener('pointerdown',e=>{const [sx,sy]=d3.pointer(e,bench),a=sx-plane.origin[0],b=sy-plane.origin[1],det=plane.xUnit[0]*plane.yUnit[1]-plane.xUnit[1]*plane.yUnit[0],x=(a*plane.yUnit[1]-b*plane.yUnit[0])/det,y=(b*plane.xUnit[0]-a*plane.xUnit[1])/det;if(x<20||x>118||y< -20||y>20)return;stop(id);inputs.sample.value=((x-20)/98*3200-1600)/P.spectral(state()).observed;render();save();});
   const ns='http://www.w3.org/2000/svg';profilePath=document.createElementNS(ns,'path');bench.querySelector('[data-line-profile]').append(profilePath);scanGroup=bench.querySelector('[data-line-scan-marker]');scanLine=document.createElementNS(ns,'path');scanDot=document.createElementNS(ns,'circle');scanLine.setAttribute('fill','none');scanLine.setAttribute('stroke','var(--anatomy-hi)');scanLine.setAttribute('stroke-width','1');scanLine.setAttribute('stroke-dasharray','2 3');scanDot.setAttribute('r','2.5');scanDot.setAttribute('fill','var(--anatomy-lit)');scanGroup.append(scanLine,scanDot);
   bench.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();stop(id);inputs.sample.value=e.key==='Home'?-4:e.key==='End'?4:+inputs.sample.value+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?.5:.05);render();save();});
  }
  function render(){const s=state(),css=getComputedStyle(document.documentElement),colors=['--gold','--cyan','--series-3','--muted'].map(t=>css.getPropertyValue(t).trim());for(const p of lab.params){$(id+'-'+p.key+'-value').textContent=fmt(s[p.key],p.key==='resolution'?0:2);inputs[p.key].setAttribute('aria-valuetext',p.label+'：'+s[p.key]);}
   let r,series,p,values;
   if(id==='line-spread'){
    r=P.spectral(s);const selected=s.sample*r.observed,span=5*r.observed,xs=[...new Set([...grid(-span,span),...grid(-5*r.before,5*r.before,301),selected,0,-r.before,r.before,-r.observed,r.observed,-r.fwhm/2,r.fwhm/2])].sort((a,b)=>a-b);
    series=[{label:'模板与恒星运动（仪器前）',data:xs.map(x=>({x,y:1-r.intrinsic(x)}))},{label:'加入仪器LSF后的观测线',data:xs.map(x=>({x,y:1-r.profile(x)}))}];
    const low=1-Math.max(r.equivalentWidth/(Math.sqrt(2*Math.PI)*r.before),r.depth)*1.15;p=BookCharts.frame(id+'-chart',{x:d3.scaleLinear().domain([-span,span]),y:d3.scaleLinear().domain([Math.max(0,low),1.025]),xLabel:'谱线速度偏移 v（km/s）',yLabel:'连续谱归一化通量 F(v)'});series.forEach((c,i)=>line(p,c.data,i===0?colors[2]:colors[0],i===0?'5 4':''));
    p.layer.append('line').attr('x1',p.x(selected)).attr('x2',p.x(selected)).attr('y1',p.y(1)).attr('y2',p.y(1-r.profile(selected))).attr('stroke',colors[0]).attr('stroke-dasharray','3 4');p.layer.append('circle').attr('cx',p.x(selected)).attr('cy',p.y(1-r.profile(selected))).attr('r',4).attr('fill',colors[0]);
    values=[r.instrument,r.observed,r.recovered===0?'零方差边界':r.recovered,fmt(1-r.profile(selected),6),r.equivalentWidth,r.fwhm];legend(series.map((c,i)=>[c.label,i===0?colors[2]:colors[0],i===0]));
    // Fixed display speed interval: the drawing changes width when the physical line does.
    const mapX=v=>20+(v+1600)/3200*98,mapY=v=>14-30*r.profile(v)/r.depth,points=grid(-1600,1600,401).map(v=>project(mapX(v),mapY(v)));
    profilePath.setAttribute('d',points.map((q,i)=>(i?'L':'M')+q.join(',')).join(''));const a=project(mapX(selected),-18),b=project(mapX(selected),18),q=project(mapX(selected),mapY(selected));scanLine.setAttribute('d','M'+a.join(',')+'L'+b.join(','));scanDot.setAttribute('cx',q[0]);scanDot.setAttribute('cy',q[1]);
    $('line-spread-bench-readout').textContent=`v=${fmt(selected,1)} km/s · F=${fmt(1-r.profile(selected),4)}`;bench.setAttribute('aria-label',`谱线读出平台，读取速度${fmt(selected,1)}km/s，归一化通量${fmt(1-r.profile(selected),4)}。左右键移动，Home和End到扫描两端。`);
    $(id+'-status').textContent=r.radicand<0?'反演方差为负：当前采用的仪器宽度与这条观测谱线不相容，不能给出实数恒星弥散。':r.recovered===0?'反演恰在零方差边界；这是无噪声模型的形式结果，真实测量仍需不确定度与分辨率分析。':r.stars<r.instrument?'恒星弥散小于仪器宽度：精确校准的无噪声模型仍能反演，但对校准误差敏感；本页不估计观测误差条。':'观测线、仪器前谱线和扫描读数使用同一卷积模型；仪器LSF假设高斯。';
    $(id+'-result').textContent=`所选 v=${fmt(selected)} km/s，吸收缺额 ${fmt(r.profile(selected),6)}，F=${fmt(1-r.profile(selected),6)}。观测总线宽 ${fmt(r.observed)} km/s；采用仪器宽度 ${fmt(r.estimated)} km/s。${r.recovered===null?'采用的校准使反演无实数解。':`反演恒星弥散 ${fmt(r.recovered)} km/s，输入为 ${fmt(r.stars)} km/s。`} 模板与观测线的速度缺额积分都为20 km/s；展宽时线变浅，面积守恒。扫描只是选点，演示时间不代表光传播或恒星轨道。`;
    Object.assign(host.dataset,{observed:r.observed,instrument:r.instrument,recovered:r.recovered===null?'':r.recovered,radicand:r.radicand,sampleVelocity:selected,sampleFlux:1-r.profile(selected)});
   }else{
    r=P.beam(s);const span=Math.max(6*r.dispersion,r.halfWidth+6*r.core),xs=grid(-span,span,801);
    series=[{label:'有限孔径与PSF混合线型',data:xs.map(x=>({x,y:r.profile(x)}))},{label:'相同二阶矩的高斯对照',data:xs.map(x=>({x,y:r.matched(x)}))},{label:'本征随机运动',data:xs.map(x=>({x,y:r.intrinsic(x)}))}];p=BookCharts.frame(id+'-chart',{x:d3.scaleLinear().domain([-span,span]),y:d3.scaleLinear().domain([0,1.1*P.gaussian(0,r.dispersion)]),xLabel:'相对中心平均速度 v（km/s）',yLabel:'归一化线型 p(v)（每 km/s）'});series.forEach((c,i)=>line(p,c.data,colors[i],i===1?'5 4':i===2?'2 4':''));values=[r.sigma,r.beamSigma,r.apertureSigma,r.sigma/r.dispersion];legend(series.map((c,i)=>[c.label,colors[i],i===1?'dashed':i===2?'dotted':'solid']));
    const svg=d3.select('#beam-smearing-section');svg.selectAll('*').remove();const extent=Math.max(1,s.aperture/2+3*r.psfSigma),x=d3.scaleLinear().domain([-extent,extent]).range([30,690]);
    for(let j=0;j<100;j++){const pos=-extent+(j+.5)*2*extent/100;svg.append('rect').attr('x',x(pos-extent/100)).attr('y',12).attr('width',6.7).attr('height',24).attr('fill',s.gradient===0?colors[3]:d3.interpolateRgb(colors[1],colors[2])((s.gradient*pos/(150*extent)+1)/2));}
    const weight=pos=>r.psfSigma===0?s.aperture===0?0:Math.abs(pos)<=s.aperture/2?1/s.aperture:0:s.aperture===0?P.gaussian(pos,r.psfSigma):Math.max(0,(P.cdf((pos+s.aperture/2)/r.psfSigma)-P.cdf((pos-s.aperture/2)/r.psfSigma))/s.aperture),positions=grid(-extent,extent,301),peak=Math.max(...positions.map(weight),1e-10),data=positions.map(pos=>({x:pos,y:weight(pos)}));
    svg.append('path').datum(data).attr('d',d3.area().x(d=>x(d.x)).y0(142).y1(d=>142-76*d.y/peak)).attr('fill',colors[0]).attr('opacity',.14);svg.append('path').datum(data).attr('d',d3.line().x(d=>x(d.x)).y(d=>142-76*d.y/peak)).attr('fill','none').attr('stroke',colors[0]).attr('stroke-width',2);svg.append('rect').attr('x',x(-s.aperture/2)).attr('y',43).attr('width',Math.max(1,x(s.aperture/2)-x(-s.aperture/2))).attr('height',10).attr('fill',colors[0]).attr('opacity',.8);if(s.seeing===0&&s.aperture===0)svg.append('line').attr('x1',x(0)).attr('x2',x(0)).attr('y1',142).attr('y2',66).attr('stroke',colors[0]).attr('stroke-width',2);
    svg.attr('aria-label',`局部速度梯度${s.gradient}km/s/kpc，孔径宽${s.aperture}kpc，PSF半高全宽${s.seeing}kpc。空间权重按自身峰值缩放，不编码光子数。`);
    $(id+'-status').textContent=s.gradient===0?'零梯度：即使空间分辨率有限，均匀同速区域也不会在此模型中额外展宽。':s.aperture===0?'无限小提取孔径极限：PSF与本征高斯卷积仍是高斯；零孔径不代表存在有限观测通量。':'有限孔径混合一般不是高斯：虚线只匹配二阶矩，不保证匹配峰值或半高全宽。';
    $(id+'-result').textContent=`σeff² = ${fmt(s.dispersion**2,2)} + ${fmt(r.beamSigma**2,2)} + ${fmt(r.apertureSigma**2,2)} = ${fmt(r.variance,2)} (km/s)²。本征、PSF、孔径的贡献按方差相加，不能把三个标准差直接相加。${s.gradient<0?'速度梯度为负，只交换接近与退行的空间位置；这个对称孔径的总线型不变。':''} 参数演示只扫描分辨率，不是星系随时间演化。`;
    Object.assign(host.dataset,{sigma:r.sigma,beamSigma:r.beamSigma,apertureSigma:r.apertureSigma,variance:r.variance});
   }
   BookCharts.setSeries(p.node,series);values.forEach((v,i)=>$(id+'-v'+i).textContent=typeof v==='string'?v:fmt(v));document.dispatchEvent(new CustomEvent('lab:render',{detail:{id:host.id}}));
  }
  function play(){if(runs.has(id)){stop(id);return;}const key=id==='line-spread'?'sample':'seeing',from=id==='line-spread'?-4:3,to=id==='line-spread'?4:0;if(motion.matches){inputs[key].value=to;render();save();return;}const button=$(id+'-play'),run={frame:0,start:performance.now(),last:0,label:button.textContent,save};runs.set(id,run);button.textContent='暂停演示';button.setAttribute('aria-pressed','true');inputs[key].value=from;render();const tick=now=>{if(document.hidden||!active(host)||motion.matches){stop(id);return;}const t=Math.min(1,(now-run.start)/9000),e=t*t*(3-2*t);if(now-run.last>110||t===1){inputs[key].value=from+(to-from)*e;render();run.last=now;}if(t<1)run.frame=requestAnimationFrame(tick);else stop(id);};run.frame=requestAnimationFrame(tick);}
  inputs.sample&&$(id+'-chart').addEventListener('pointerdown',e=>{const p=BookCharts.inspect(id+'-chart'),[x,y]=d3.pointer(e,$(id+'-chart'));if(!p||x<p.box.x||x>p.box.x+p.box.w||y<p.box.y||y>p.box.y+p.box.h)return;stop(id);inputs.sample.value=p.x.invert(x)/P.spectral(state()).observed;render();save();});
  for(const input of Object.values(inputs))input.addEventListener('input',()=>{stop(id);render();save();});$(id+'-play').onclick=play;$(id+'-reset').onclick=()=>{stop(id);lab.params.forEach(p=>inputs[p.key].value=p.value);render();save();};$(id+'-question').onclick=()=>window.showTutor(`第${lab.chapter}章「${lab.title}」。教材依据：${lab.source}。参数：${JSON.stringify(state())}。读数：${lab.values.map((name,i)=>name+'='+$(id+'-v'+i).textContent).join('；')}。模型边界：${lab.assumptions}。请独立核对卷积、归一化、二阶矩与符号，区分原书内容和新增推导。`);
  new IntersectionObserver(es=>{if(es.some(e=>!e.isIntersecting))stop(id);}).observe(host);controllers.push({id,host,render});render();
 }
 document.addEventListener('reader:pagechange',()=>{for(const r of controllers)if(active(r.host))requestAnimationFrame(r.render);else stop(r.id);});document.addEventListener('visibilitychange',()=>{if(document.hidden)[...runs.keys()].forEach(stop);});motion.addEventListener('change',()=>{if(motion.matches)[...runs.keys()].forEach(stop);});let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>controllers.filter(r=>active(r.host)).forEach(r=>r.render()),140);});
})();
